/**
 * Icon for a section landing, by its path segment.
 *
 * @param string $section Section slug.
 * @return string Icon name.
 */
function section_icon( $section ) {
	$map = array(
		'get-started' => 'home',
		'write'       => 'edit',
		'blocks'      => 'block',
		'design'      => 'styles',
		'manage'      => 'cog',
		'ai'          => 'sparkles',
		'classic'     => 'archive',
	);
	return $map[ $section ] ?? 'page';
}
